/**
 * A bar chart for comparing magnitudes across categories (`design/components/bar-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/bar-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  DEFAULT_CHART_MESSAGES,
  Each,
  Icon,
  UNMEASURED,
  agentMember,
  barChartModel,
  barChartReadout,
  barChartSelection,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartSeries,
  chooseChartMark,
  claimSlot,
  createCell,
  createDerived,
  createReading,
  createWarningLog,
  devWarning,
  elementRef,
  measureBox,
  nearestIndex,
  readChartPosition,
  readingRest,
  readingView,
  scope,
  toggleChartSeries,
  toggleSeries,
  watchEffect,
  type ChartAnnotation,
  type ChartBaseline,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type ChartXAxis,
  type ChartYAxis,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/charts/bar-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartNotes from '@polymorph/recipes/charts/frame/chart-annotations.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button'
import Table from '../structure/Table'
import TableBody from '../structure/TableBody'
import TableCell from '../structure/TableCell'
import TableHead from '../structure/TableHead'
import TableHeader from '../structure/TableHeader'
import TableRow from '../structure/TableRow'

export interface BarChartProps {
  /**
   * Annotations from the closed union above: line, band and point, literals only. The frame's
   * shared annotation layer draws them in `--pm-chart-axis`, with bands washed in
   * `--pm-chart-other` at 0.08. An annotation never re-centres colour. Colliding labels are
   * dropped, but the annotation itself always draws because the app asked for it explicitly.
   */
  annotations?: readonly ChartAnnotation[]
  baseline?: ChartBaseline
  /**
   * The data rows. `[]` renders the built-in empty state.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * Key of the series to emphasise. It keeps its slot colour and the rest use
   * `--pm-chart-other`. A status-toned series keeps its status colour, because reserved meaning
   * is never greyed out.
   */
  emphasis?: string
  /**
   * The chart's accessible name. It is required, as for Progress, because an unnamed chart tells
   * a reader nothing.
   */
  label: string
  /**
   * Series drawn as lines over the bars, on the bars' value axis and in their unit: a moving
   * average of the bars' own measure, say. They take the slots after the bars'. A vertical chart
   * only; a horizontal one warns and draws no lines. A second measure on a scale of its own is a
   * second chart.
   */
  lines?: readonly ChartSeries[]
  /**
   * Loading state. On first render the frame shows a quiet `Skeleton`; on refetch it shows the
   * previous frame at reduced opacity, with no layout jump or flash. Failure is not a chart
   * state: the app reports errors, and a chart shows only data, never network status.
   */
  loading?: boolean
  /**
   * The locale `Intl` formats with. When omitted, the runtime's own resolved locale applies.
   */
  locale?: string
  /**
   * The tier's message catalog. When omitted, the generic English defaults apply. A localized
   * host passes its own, the same object to every chart on the screen.
   */
  messages?: ChartMessages
  /**
   * How multiple series combine; applies at 2 or more series. Mixed signs cannot stack, so
   * `stacked` with both signs dev-warns and renders grouped. `diverging` is the Likert form on
   * `stackOffsetDiverging`. **The app splits neutral answers**: it pre-signs values, and the
   * member never derives a neutral key. Each side's segments take the diverging arms outward
   * from zero. In this mode the warning is reversed, because signed data is expected.
   */
  mode?: 'grouped' | 'stacked' | 'diverging'
  /**
   * Called with the row index, series key and row at the reading position, on Enter, Space or
   * click.
   */
  onSelect?: (selection: {
    index: number
    key: string
    datum: Readonly<Record<string, string | number | null>>
  }) => void
  /**
   * Use horizontal for long category names, because the system never rotates a label.
   */
  orientation?: 'horizontal' | 'vertical'
  /**
   * The series to draw, 1–8. A ninth gets a dev-warning about folding into "Other", never a
   * generated hue, because the wheel has eight seats.
   */
  series: readonly ChartSeries[]
  /**
   * Frame height, from `--pm-chart-height-*`. The frame never nests a scroll region.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Tooltip configuration, on with `'dot'` by default. `false`, for print and report surfaces,
   * removes only the visual layer.
   */
  tooltip?: false | ChartTooltipConfig
  x: ChartXAxis
  /**
   * Y axis configuration. The axis renders by default.
   */
  y?: ChartYAxis
}

/** A bar chart for comparing magnitudes across categories. */
export default function BarChart(given: BarChartProps): JSX.Element {
  const props = mergeProps(
    {
      orientation: 'vertical',
      mode: 'grouped',
      size: 'md',
      tooltip: (() => ({}))(),
      loading: false,
      messages: (() => DEFAULT_CHART_MESSAGES)(),
    } as Defaults<
      BarChartProps,
      'orientation' | 'mode' | 'size' | 'tooltip' | 'loading' | 'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const frame = elementRef<HTMLElement>()
    const plot = elementRef<HTMLElement>()
    const box = createCell(UNMEASURED)
    const reading = createCell(createReading({ count: 0, seriesStart: null }))
    const position = createCell(readingRest(null))
    const hidden = createCell(new Set<string>())
    const twinOpen = createCell(false)
    const warningLog = createCell(createWarningLog())
    const input = createDerived(() => ({
      data: props.data,
      series: props.series,
      lines: props.lines,
      x: props.x,
      y: props.y,
      orientation: props.orientation,
      mode: props.mode,
      emphasis: props.emphasis,
      baseline: props.baseline,
      annotations: props.annotations,
      label: props.label,
      locale: props.locale,
      messages: props.messages,
      tooltip: props.tooltip,
      loading: props.loading,
      selectable: props.onSelect !== undefined,
      hidden: hidden.value,
      box: box.value,
    }))
    const model = createDerived(() => barChartModel(input.value))
    const view = createDerived(() =>
      readingView(position.value, props.data.length, model.value.visible.length),
    )
    const readout = createDerived(() => barChartReadout(input.value, model.value, view.value))
    const activate = createDerived(() => () => {
      const selection = barChartSelection(input.value, model.value, reading.value.now())
      if (selection !== null) props.onSelect?.(selection)
    })
    const walk = createDerived(() => ({
      count: props.data.length,
      seriesCount: model.value.visible.length,
      walkSeries: true,
    }))
    const marks = createDerived(() => ({
      walk: walk.value,
      input: input.value,
      model: model.value,
      readout: barChartReadout,
      selection: barChartSelection,
    }))
    const onKey = createDerived(() => (event: KeyboardEvent) => {
      if (props.onSelect !== undefined && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault()
        activate.value()
        return
      }
      reading.value.update(walk.value)
      if (reading.value.key(event.key)) event.preventDefault()
    })
    const onPointer = createDerived(() => (event: PointerEvent) => {
      if (model.value.plot === null) return
      const rect = (event.currentTarget as Element).getBoundingClientRect()
      reading.value.moveTo(
        nearestIndex(
          model.value.positions,
          model.value.vertical ? event.clientX - rect.left : event.clientY - rect.top,
        ),
        reading.value.now().series,
      )
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [plot.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      reading.value.subscribe((now) => {
        position.value = now
      })
    }
    onMount(effect2)
    const effect3 = () => {
      warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
    }
    watchEffect(
      createMemo(() => model.value.warnings.join('\n')),
      effect3,
      true,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran =
        !(props.onSelect !== undefined) && !model.value.legend
          ? () => {}
          : agentMember({
              member: 'BarChart',
              element: () => frame.value,
              state: () => ({
                items: props.onSelect !== undefined ? chartMarks(marks.value, reading.value) : [],
                position: chartPosition(marks.value, reading.value),
                count: walk.value.count,
                series: chartSeries(frame.value, chartLegend.key, model.value.painted),
                hidden: chartHiddenSeries(frame.value, chartLegend.key, model.value.painted),
              }),
              actions: {
                read: {
                  argument: 'number',
                  run: (value) => readChartPosition(marks.value, value, reading.value),
                },
                choose: {
                  argument: 'id',
                  among: 'items',
                  run: (value) =>
                    chooseChartMark(marks.value, value, reading.value, activate.value),
                },
                toggle: {
                  argument: 'id',
                  among: 'series',
                  run: (value) =>
                    toggleChartSeries(frame.value, chartLegend.key, model.value.painted, value),
                },
              },
            })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <figure
        class={chartFrame.frame}
        data-size={props.size}
        data-state={model.value.state}
        data-position={view.value.active ? view.value.index : undefined}
        aria-label={props.label}
        data-member="bar-chart"
        ref={frame.attach}
      >
        {/* region */}
        <div class={chartFrame.region}>
          {/* y axis */}
          <div class={chartFrame.yAxis}>
            {model.value.axes?.y !== undefined ? (
              <div class={chartAxis.axis} data-orientation="y" aria-hidden="true">
                <Each of={model.value.axes?.y ?? []} by={(tick) => tick.key} renew>
                  {(tick) => (
                    <span
                      class={chartAxis.tick}
                      style={{ top: `${tick.at}px` }}
                      data-align={tick.align}
                    >
                      {tick.label}
                    </span>
                  )}
                </Each>
              </div>
            ) : null}
          </div>
          {/* plot */}
          <div class={chartFrame.plot} ref={plot.attach}>
            {model.value.state === 'empty' ? (
              <div class={chartFrame.empty}>
                <span>{props.messages.empty}</span>
              </div>
            ) : (
              <div
                class={styles.surface}
                tabindex="0"
                role="img"
                aria-label={props.label}
                onkeydown={($event: KeyboardEvent) => onKey.value($event)}
                onclick={() => activate.value()}
                onpointermove={($event: PointerEvent) => onPointer.value($event)}
                onpointerleave={() => reading.value.clear()}
                onblur={() => reading.value.clear()}
              >
                {model.value.plot !== null ? (
                  <svg
                    class={styles.marks}
                    style={{ '--pm-chart-zero': `${model.value.plot?.zero}px` }}
                    data-orientation={props.orientation}
                    data-mode={model.value.drawn}
                    data-reading={view.value.active ? '' : undefined}
                    width={model.value.plot?.width}
                    height={model.value.plot?.height}
                    aria-hidden="true"
                    {...{ focusable: 'false' }}
                  >
                    {/* grid */}
                    <g class={styles.grid}>
                      <Each of={model.value.plot?.grid ?? []} by={(line) => line.key} renew>
                        {(line) => <path d={line.d} />}
                      </Each>
                    </g>
                    {(model.value.plot?.wash ?? []).length > 0 ? (
                      <g class={chartNotes.washes}>
                        <Each of={model.value.plot?.wash ?? []} by={(span) => span.key} renew>
                          {(span) => (
                            <rect
                              class={chartNotes.span}
                              x={span.x}
                              y={span.y}
                              width={span.width}
                              height={span.height}
                            />
                          )}
                        </Each>
                      </g>
                    ) : null}
                    {/* bands */}
                    <g class={styles.bands}>
                      <Each of={model.value.plot?.bands ?? []} by={(band) => band.key} renew>
                        {(band) => (
                          <g data-active={view.value.index === band.index ? '' : undefined}>
                            <rect
                              class={styles.hit}
                              x={band.hit.x}
                              y={band.hit.y}
                              width={band.hit.width}
                              height={band.hit.height}
                              onpointerenter={() =>
                                reading.value.moveTo(band.index, reading.value.now().series)
                              }
                            />
                            <Each of={band.marks} by={(mark) => mark.key} renew>
                              {(mark) => (
                                <path
                                  class={styles.bar}
                                  style={{ '--pm-chart-mark': mark.paint }}
                                  data-active={
                                    view.value.index === band.index &&
                                    view.value.series === mark.series
                                      ? ''
                                      : undefined
                                  }
                                  d={mark.d}
                                />
                              )}
                            </Each>
                          </g>
                        )}
                      </Each>
                    </g>
                    {/* zero */}
                    <path class={styles.zero} d={model.value.plot?.zeroRule} />
                    {(model.value.plot?.ink ?? null) !== null ? (
                      <g class={chartNotes.ink}>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.spans ?? []}
                          by={(span) => span.key}
                          renew
                        >
                          {(span) => (
                            <g>
                              <path class={chartNotes.edge} d={span.from} />
                              <path class={chartNotes.edge} d={span.to} />
                            </g>
                          )}
                        </Each>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.rules ?? []}
                          by={(rule) => rule.key}
                          renew
                        >
                          {(rule) => <path class={chartNotes.rule} d={rule.d} />}
                        </Each>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.marks ?? []}
                          by={(mark) => mark.key}
                          renew
                        >
                          {(mark) => (
                            <circle class={chartNotes.mark} cx={mark.cx} cy={mark.cy} r={mark.r} />
                          )}
                        </Each>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.labels ?? []}
                          by={(note) => note.key}
                          renew
                        >
                          {(note) => (
                            <text
                              class={chartNotes.label}
                              x={note.x}
                              y={note.y}
                              text-anchor={note.anchor}
                            >
                              {note.text}
                            </text>
                          )}
                        </Each>
                      </g>
                    ) : null}
                    {(model.value.plot?.lines ?? []).length > 0 ? (
                      <g class={styles.lines}>
                        <Each of={model.value.plot?.lines ?? []} by={(line) => line.key} renew>
                          {(line) => (
                            <g style={{ '--pm-chart-mark': line.paint }}>
                              <path class={styles.line} d={line.d} />
                              <Each of={line.points} by={(point) => point.key} renew>
                                {(point) => (
                                  <circle
                                    class={styles.point}
                                    cx={point.cx}
                                    cy={point.cy}
                                    r={point.r}
                                    data-active={
                                      view.value.index === point.index &&
                                      (view.value.series === null ||
                                        view.value.series === line.series)
                                        ? ''
                                        : undefined
                                    }
                                  />
                                )}
                              </Each>
                            </g>
                          )}
                        </Each>
                      </g>
                    ) : null}
                  </svg>
                ) : null}
              </div>
            )}
            {readout.value.tooltip !== null ? (
              <div
                class={chartTooltip.tooltip}
                style={{
                  '--pm-chart-tip-x': `${readout.value.tooltip?.x}px`,
                  '--pm-chart-tip-y': `${readout.value.tooltip?.y}px`,
                }}
                data-indicator={readout.value.tooltip?.indicator}
                data-side={readout.value.tooltip?.side}
                aria-hidden="true"
              >
                {readout.value.tooltip?.header !== undefined ? (
                  <p class={chartTooltip.header}>{readout.value.tooltip?.header}</p>
                ) : null}
                <ul class={chartTooltip.rows}>
                  <Each of={readout.value.tooltip?.rows ?? []} by={(row) => row.key} renew>
                    {(row) => (
                      <li class={chartTooltip.row}>
                        <span class={chartTooltip.key} style={{ '--pm-chart-key': row.paint }} />
                        <span class={chartTooltip.value}>{row.value}</span>
                        <span class={chartTooltip.label}>{row.label}</span>
                      </li>
                    )}
                  </Each>
                </ul>
              </div>
            ) : null}
          </div>
          {/* x axis */}
          <div class={chartFrame.xAxis}>
            {model.value.axes?.x !== undefined ? (
              <div class={chartAxis.axis} data-orientation="x" aria-hidden="true">
                <Each of={model.value.axes?.x ?? []} by={(tick) => tick.key} renew>
                  {(tick) => (
                    <span
                      class={chartAxis.tick}
                      style={{ left: `${tick.at}px` }}
                      data-align={tick.align}
                    >
                      {tick.label}
                    </span>
                  )}
                </Each>
              </div>
            ) : null}
          </div>
        </div>
        {model.value.legend ? (
          model.value.painted.length > 0 ? (
            <ul class={styles.legend} data-key-shape="rect">
              <Each of={model.value.painted} by={(entry) => entry.key} renew>
                {(entry) => (
                  <li
                    class={chartLegend.item}
                    data-key-shape={model.value.lineKeys.includes(entry.key) ? 'line' : undefined}
                  >
                    <button
                      class={chartLegend.key}
                      type="button"
                      aria-pressed={hidden.value.has(entry.key) ? 'false' : 'true'}
                      onclick={() => (hidden.value = toggleSeries(hidden.value, entry.key))}
                    >
                      <span
                        class={chartLegend.swatch}
                        style={{ '--pm-chart-key': entry.paint }}
                        aria-hidden="true"
                      />
                      {entry.icon !== undefined ? (
                        <span class={chartLegend.glyph}>
                          <Icon name={entry.icon} size="sm" />
                        </span>
                      ) : null}
                      <span class={chartLegend.label}>{entry.label}</span>
                    </button>
                  </li>
                )}
              </Each>
            </ul>
          ) : null
        ) : null}
        {/* summary */}
        <span class={a11y.visuallyHidden}>{model.value.summary}</span>
        {/* twin */}
        <div class={chartTwin.twin} data-state={twinOpen.value ? 'open' : 'closed'}>
          <div class={chartTwin.toggle}>
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              icon="table"
              iconOnly={true}
              label={
                twinOpen.value
                  ? props.messages.hideTable(props.label)
                  : props.messages.showTable(props.label)
              }
              onClick={() => (twinOpen.value = !twinOpen.value)}
            />
          </div>
          {twinOpen.value ? (
            <div class={chartTwin.table}>
              <Table
                label={props.messages.tableLabel(props.label)}
                caption={props.messages.tableLabel(props.label)}
              >
                <TableHead>
                  <TableRow>
                    <Each of={model.value.twin.columns} by={(column) => column.key} renew>
                      {(column) => (
                        <TableHeader numeric={column.numeric}>{column.label}</TableHeader>
                      )}
                    </Each>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <Each of={model.value.twin.rows} by={(_row, line) => line} renew>
                    {(row) => (
                      <TableRow>
                        <Each
                          of={row}
                          by={(_cell, cellIndex) =>
                            model.value.twin.columns[cellIndex]?.key ?? cellIndex
                          }
                          renew
                        >
                          {(cell, cellIndex) => (
                            <TableCell numeric={model.value.twin.columns[cellIndex()]?.numeric}>
                              {cell === '' ? '—' : cell}
                            </TableCell>
                          )}
                        </Each>
                      </TableRow>
                    )}
                  </Each>
                </TableBody>
              </Table>
            </div>
          ) : null}
        </div>
        {/* live region */}
        <span class={a11y.visuallyHidden}>
          <div aria-live="polite" aria-atomic="true">
            {readout.value.announcement}
          </div>
        </span>
      </figure>
    )
  })
}
